<?php
// Detail dokumen (situs). GET slug: tampil (tamu = ajakan masuk, login = tombol baca/unduh).
// ?unduh=1 kirim PDF sebagai unduhan, ?baca=1 tampil di browser; keduanya wajib login (K-02).
// Hanya dokumen status 'terbit' (K-07); selain itu atau tidak ada -> 404.
require_once 'config/config.php';

// Path file PDF yang aman: harus di bawah uploads/pdf/ (cegah path traversal). null = tidak ada.
function berkasPdf($path) {
    if (!is_string($path) || strpos($path, 'uploads/pdf/') !== 0) return null;
    $folder = realpath(ROOT_PATH . 'uploads/pdf');
    $file = realpath(ROOT_PATH . $path);
    if (!$folder || !$file || strpos($file, $folder . DIRECTORY_SEPARATOR) !== 0 || !is_file($file)) return null;
    return $file;
}

$slug = is_string($_GET['slug'] ?? null) ? $_GET['slug'] : '';
$unduh = ($_GET['unduh'] ?? '') === '1';
$baca = ($_GET['baca'] ?? '') === '1';
if ($unduh || $baca) {
    requireLogin(); // tamu -> masuk.php
}

$d = new Dokumen((new Database())->getConnection());
$ada = $slug !== '' && strlen($slug) <= 100 && $d->readBySlug($slug) && $d->status === 'terbit';
$berkas = $ada ? berkasPdf($d->file_pdf) : null;

if ($ada && $unduh && !(int) $d->bisa_unduh) {
    http_response_code(403); // K-20
    header('Content-Type: text/plain; charset=utf-8');
    exit('Dokumen ini tidak dapat diunduh.');
}

if (!$ada || (($unduh || $baca) && !$berkas)) {
    http_response_code(404);
    $judul = 'Halaman tidak ditemukan';
    $halaman_aktif = '';
    include ROOT_PATH . 'partials/head.php';
    include ROOT_PATH . 'partials/site_header.php';
    ?>
<main id="isi" class="situs-main"><div class="situs-main__box--py-16-text-center-justify-center"><div class="situs-main__box--bg-primary-soft-place-items-center-rounded-2xl has-size"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="situs-main__icon situs-main__icon--size-7 has-size" aria-hidden="true"><path d="M6 22a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.704.706l3.588 3.588A2.4 2.4 0 0 1 20 8v12a2 2 0 0 1-2 2z"></path><path d="M12 17h.01"></path><path d="M9.1 9a3 3 0 0 1 5.82 1c0 2-3 3-3 3"></path></svg></div><p class="situs-main__paragraph--mt-5-text-hz-overline-uppercase">Kode 404</p><h1 class="situs-main__title--mt-1-5">Halaman tidak ditemukan</h1><p class="situs-main__paragraph--max-w-md-mt-2-text-hz-body">Tautannya mungkin salah ketik, atau halamannya sudah dipindah.</p><div class="situs-main__box--mt-6-gap-2-w-full"><a data-slot="button" data-variant="default" data-size="lg" class="button button--px-6-text-hz-body-lg-medium-bg-primary-text-primary-foreground group/button has-size" href="<?= BASE_URL ?>index.php"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="button__icon button__icon--size-4 has-size" aria-hidden="true"><path d="M15 21v-8a1 1 0 0 0-1-1h-4a1 1 0 0 0-1 1v8"></path><path d="M3 10a2 2 0 0 1 .709-1.528l7-6a2 2 0 0 1 2.582 0l7 6A2 2 0 0 1 21 10v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"></path></svg>Ke Beranda</a><a data-slot="button" data-variant="outline" data-size="lg" class="button button--px-6-text-hz-body-lg-medium-border-input-bg-card group/button has-size" href="<?= BASE_URL ?>jelajah.php"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="button__icon button__icon--size-4 has-size" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m16.24 7.76-1.804 5.411a2 2 0 0 1-1.265 1.265L7.76 16.24l1.804-5.411a2 2 0 0 1 1.265-1.265z"></path></svg>Jelajah koleksi</a></div></div></main>
    <?php
    include ROOT_PATH . 'partials/site_footer.php';
    exit();
}

// Kirim PDF
if ($unduh || $baca) {
    $nama = trim(preg_replace('/[^A-Za-z0-9._-]+/', '-', $d->judul), '-');
    $nama = ($nama !== '' ? substr($nama, 0, 80) : $d->slug) . '.pdf';
    while (ob_get_level() > 0) ob_end_clean();
    header('Content-Type: application/pdf');
    header('Content-Disposition: ' . ($unduh ? 'attachment' : 'inline') . '; filename="' . $nama . '"');
    header('Content-Length: ' . filesize($berkas));
    header('X-Content-Type-Options: nosniff');
    if ($unduh) $d->tambahUnduhan();
    readfile($berkas);
    exit();
}

// Tampilan detail
$d->tambahDibaca();
$d->dibaca++;
$login = isLoggedIn();
$adaPdf = (bool) $berkas;
$urlBaca = BASE_URL . 'dokumen.php?slug=' . rawurlencode($d->slug) . '&baca=1';
$urlUnduh = BASE_URL . 'dokumen.php?slug=' . rawurlencode($d->slug) . '&unduh=1';
$jenisLabel = Dokumen::JENIS[$d->jenis] ?? $d->jenis;
$aksesLabel = Dokumen::AKSES[$d->akses] ?? $d->akses;
$halaman = $d->halaman > 0 ? (int) $d->halaman : '-';
$halamanTeks = $d->halaman > 0 ? $d->halaman . ' halaman' : '-';
$kata = array_values(array_filter(array_map('trim', explode(',', (string) $d->kata_kunci)), 'strlen'));

$judul = $d->judul;
$halaman_aktif = '';
include ROOT_PATH . 'partials/head.php';
include ROOT_PATH . 'partials/site_header.php';
?>
